package sshgrant

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/nolith/geas/internal/secretfile"
	"github.com/nolith/geas/internal/sessiondir"
)

// The files in an agent's directory: its key, generated by the first grant,
// and the certificate the latest grant signed.
const (
	KeyFile         = "id_ed25519"
	PublicKeyFile   = "id_ed25519.pub"
	CertificateFile = "id_ed25519-cert.pub"
)

// The agent's copies in a session's directory, which the sshcert provider
// writes, and the ssh_config that uses them.
const (
	SessionKey         = "ssh/" + KeyFile
	SessionCertificate = "ssh/" + CertificateFile
	SessionConfig      = "ssh/config"
)

// AgentsDir is $XDG_STATE_HOME/geas/agents, one directory per agent, each
// owner-only: no agent may read another's key.
func AgentsDir() (string, error) {
	state, err := secretfile.StateDirectory()
	if err != nil {
		return "", err
	}
	return filepath.Join(state, "agents"), nil
}

// agentName is what Slug makes of a name: what an agent's directory and its
// certificate's key ID may be called.
var agentName = regexp.MustCompile(`^[a-z0-9]+(-[a-z0-9]+)*$`)

// AgentDir is the directory of the agent name, which must be a slug.
func AgentDir(name string) (string, error) {
	if !agentName.MatchString(name) {
		return "", errors.New("bad agent name: " + name)
	}
	agents, err := AgentsDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(agents, name), nil
}

// Slug lowercases s and keeps [a-z0-9-] only, with no leading, trailing or
// repeated dashes: any other byte becomes a dash.
func Slug(s string) string {
	var b strings.Builder
	dash := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= 'A' && c <= 'Z' {
			c += 'a' - 'A'
		}
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') {
			dash = b.Len() > 0
			continue
		}
		if dash {
			b.WriteByte('-')
			dash = false
		}
		b.WriteByte(c)
	}
	return b.String()
}

// show prints the certificate of the agent name.
func show(output io.Writer, name string) error {
	dir, err := AgentDir(name)
	if err != nil {
		return err
	}
	raw, err := os.ReadFile(filepath.Join(dir, CertificateFile))
	if errors.Is(err, os.ErrNotExist) {
		return errors.New(name + " has no certificate")
	}
	if err != nil {
		return err
	}
	c, err := ParseCertificate(raw)
	if err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	_, err = io.WriteString(output, c.Describe())
	return err
}

// showSession prints the certificate the session GEAS_SESSION_DIR names
// holds for the agent name, and the configuration to connect with.
func showSession(output io.Writer, name string) error {
	dir, err := sessiondir.FromEnv()
	if err != nil {
		return err
	}
	if name == "" {
		name = "this agent"
	}
	raw, err := dir.ReadFile(SessionCertificate)
	if errors.Is(err, os.ErrNotExist) {
		return errors.New(name + " has no certificate in this session: ask the human: geas ssh grant " + name + " <host>")
	}
	if err != nil {
		return err
	}
	c, err := ParseCertificate(raw)
	if err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	config, err := dir.Join(SessionConfig)
	if err != nil {
		return err
	}
	_, err = io.WriteString(output, c.Describe()+"config: "+config+"\n")
	return err
}

// list prints every agent with a key, one line each: its name, and until
// when its certificate is valid and for which hosts.
func list(output io.Writer, now time.Time) error {
	agents, err := AgentsDir()
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(agents)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	var names []string
	for _, e := range entries {
		if _, err := os.Stat(filepath.Join(agents, e.Name(), KeyFile)); err == nil && e.IsDir() && agentName.MatchString(e.Name()) {
			names = append(names, e.Name())
		}
	}
	if len(names) == 0 {
		_, err = fmt.Fprintln(output, "no agent has a key")
		return err
	}
	width := 0
	for _, name := range names {
		width = max(width, len(name))
	}
	for _, name := range names {
		state := "no certificate"
		if raw, err := os.ReadFile(filepath.Join(agents, name, CertificateFile)); err == nil {
			state = summary(raw, now)
		}
		if _, err = fmt.Fprintf(output, "%-*s  %s\n", width, name, state); err != nil {
			return err
		}
	}
	return nil
}

// summary is one line about a certificate: until when it is valid, or since
// when it is not, and its principals.
func summary(raw []byte, now time.Time) string {
	c, err := ParseCertificate(raw)
	if err != nil {
		return "unreadable certificate"
	}
	state := "until " + c.Expires().Format("2006-01-02 15:04 MST")
	switch {
	case c.Expires().IsZero():
		state = "valid forever"
	case !c.ValidAt(now) && now.Before(c.Expires()):
		state = "not valid yet"
	case !c.ValidAt(now):
		state = "expired " + c.Expires().Format("2006-01-02 15:04 MST")
	}
	return state + ": " + strings.Join(c.Principals, " ")
}

// drop deletes the agent's key and certificate, and its directory.
func drop(output io.Writer, name string) error {
	dir, err := AgentDir(name)
	if err != nil {
		return err
	}
	if info, err := os.Stat(dir); err != nil || !info.IsDir() {
		return errors.New(name + " has nothing to drop")
	}
	for _, file := range []string{KeyFile, PublicKeyFile, CertificateFile} {
		if err = os.Remove(filepath.Join(dir, file)); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	if err = os.Remove(dir); err != nil {
		return err
	}
	_, err = fmt.Fprintf(output, "Dropped %s.\n", name)
	return err
}
